local _, WFJ = ...
WFJ.Data.add("book", {
  ["bc428d38d6421eb8"] = { "Disperato nel cercare una cura per la dipendenza dalla magia che affliggeva la sua razza, Kael fece l'impensabile: abbracciò l'eredità degli ⟦Highborne=Alti Nobili⟧, antenati del suo popolo, e si unì a Illidan e ai suoi naga nella speranza di trovare una nuova fonte di potere magico di cui nutrirsi. I comandanti rimasti dell'⟦Alliance=Alleanza⟧ condannarono gli elfi del sangue come traditori e li bandirono per sempre.", "." },
  ["bc92a0e78d6b3a68"] = { "Sapendo bene dove avrebbero portato i piani spietati di Illidan, Malfurion decise di occuparsi una volta per tutte del fratello assetato di potere. Con l'aiuto di Cenarius, Malfurion rinchiuse Illidan in un'immensa prigione sotterranea, dove sarebbe rimasto incatenato e privo di poteri fino alla fine dei tempi. Per assicurarsi che il fratello restasse prigioniero, Malfurion conferì alla giovane sorvegliante Maiev Shadowsong il compito di essere la carceriera personale di Illidan.", "." },
  ["bca3588cd665992c"] = { "Ipotizzò che gli orchi fossero stati corrotti da quei poteri ancor prima della loro prima invasione di Azeroth. Era chiaro che i demoni avevano contaminato il sangue degli orchi, e che in cambio quei bruti avevano ottenuto forza, resistenza e aggressività accresciute in modo innaturale.", "." },
  ["bcc1d6810c09f040"] = { "Vostro Onore,\n\nmi rincresce informarvi che al momento i Guardiani della Notte non possono lasciare il loro posto a ⟦Darkshire=Borgoscuro⟧. Forse non sapevate che ⟦Stormwind=Roccavento⟧ non fornisce più sostegno militare in questa regione. I Guardiani della Notte sono stati formati e addestrati interamente dalla gente della foresta per difendere ⟦Darkshire=Borgoscuro⟧ in assenza di ⟦Stormwind=Roccavento⟧. Senza i Guardiani, la città cadrebbe. Vi auguro buona fortuna nella vostra difficile situazione.\n\n--Lord Ello Ebonlocke", "." },
  ["bcd1b8ebec02906f"] = { "Salute, {name}. Ho pensato che i risultati delle mie ricerche potessero interessarti.\n\nA quanto pare, sia Reuben sia Leagrem hanno lasciato dei familiari, per così dire. Anche se sanno già quale sorte sia toccata al soldato perduto, far visita a uno di loro potrebbe valerne la pena.\n\nL'ex moglie di Reuben, Joanna Whitehall, la trovi nel ⟦War Quarter=Quartiere della Guerra⟧ di Sepulcra, dove passa la maggior parte del tempo. Bada, però: non so quanto accoglierà volentieri la notizia.\n\nQuanto a Leagrem, sua zia è diventata la matrona dell'orfanotrofio di ⟦Stormwind=Roccavento⟧, un incarico ammirevole.\n\nQualunque sia la strada che prenderai nella vita, ti auguro buona fortuna nelle tue imprese.", "." },
  ["bce889d2e65d83a4"] = { "Il piano del Re dei Lich funzionò alla perfezione. Molti villaggi del nord di Lordaeron furono contaminati quasi subito. Proprio come in Nordania, i cittadini che contraevano la pestilenza morivano e risorgevano come schiavi devoti del Re dei Lich.", "." },
})
